    frame = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 5]
    top = min(r for r, c in frame)
    bottom = max(r for r, c in frame)
    left = min(c for r, c in frame)
    right = max(c for r, c in frame)

    inner_rows = list(range(top + 1, bottom))
    inner_cols = list(range(left + 1, right))
    row_mid = len(inner_rows) // 2
    col_mid = len(inner_cols) // 2
    row_parts = (inner_rows[:row_mid], inner_rows[row_mid:])
    col_parts = (inner_cols[:col_mid], inner_cols[col_mid:])

    quadrants = {
        "TL": (row_parts[0], col_parts[0]),
        "TR": (row_parts[0], col_parts[1]),
        "BL": (row_parts[1], col_parts[0]),
        "BR": (row_parts[1], col_parts[1]),
    }
    paired = {"TL": "BR", "TR": "BL", "BL": "TR", "BR": "TL"}

    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color == 0 or color == 5:
                continue
            if r < top:
                corner = "TL" if c < left else "TR"
            elif r > bottom:
                corner = "BL" if c < left else "BR"
            elif c < left:
                corner = "TL" if r < top else "BL"
            else:
                corner = "TR" if r < top else "BR"

            for quadrant in (corner, paired[corner]):
                rows, cols = quadrants[quadrant]
                for rr in rows:
                    for cc in cols:
                        out[rr][cc] = color

    return out
